<?php
declare(strict_types=1);
use App\Models\{Club,User};use App\Services\Finance\ClubInternalTransferService;use App\Services\Finance\Exceptions\ClubInternalTransferConflictException;
require dirname(__DIR__,2).'/vendor/autoload.php';$app=require dirname(__DIR__,2).'/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();[$requestPath,$barrier,$worker]=array_slice($argv,1);$request=json_decode((string)file_get_contents($requestPath),true,flags:JSON_THROW_ON_ERROR);file_put_contents($barrier.DIRECTORY_SEPARATOR."ready.{$worker}",'1');$deadline=microtime(true)+20;while(!file_exists($barrier.DIRECTORY_SEPARATOR.'go')){if(microtime(true)>=$deadline)throw new RuntimeException('Barrier timeout.');usleep(10000);}try{$transfer=app(ClubInternalTransferService::class)->record(Club::findOrFail($request['club']),User::findOrFail($request['actor']),$request['payload']);$result=['status'=>'success','transfer'=>$transfer->public_id,'journal'=>$transfer->journalEntry->public_id];}catch(ClubInternalTransferConflictException){$result=['status'=>'conflict','code'=>'TRANSFER_IDEMPOTENCY_CONFLICT'];}catch(Throwable $e){$result=['status'=>'error','class'=>$e::class,'message'=>$e->getMessage()];}file_put_contents($barrier.DIRECTORY_SEPARATOR."result.{$worker}.json",json_encode($result,JSON_THROW_ON_ERROR));
